import hashlib

def release_lock(run,path,approved_id,approved_owner,caller,force_authorized,local_bytes,approved_local_sha256):
    if not isinstance(local_bytes,bytes) or hashlib.sha256(local_bytes).hexdigest()!=approved_local_sha256:
        raise ValueError("preserve and approve current offline bytes before release")
    if type(force_authorized) is not bool or not all(isinstance(v,str) and v for v in (path,approved_id,approved_owner,caller)):
        raise ValueError("explicit lock identity and policy required")
    locks=run(["lfs","locks","--json","--path="+path])
    if not isinstance(locks,list) or len(locks)!=1:raise ValueError("one current lock required")
    lock=locks[0]
    if lock["path"]!=path or lock["id"]!=approved_id or lock["owner"]["name"]!=approved_owner:
        raise ValueError("approved lock generation or owner changed")
    foreign=caller!=approved_owner
    if foreign and not (caller=="admin" and force_authorized):
        raise PermissionError("foreign lock requires separate reviewed admin takeover")
    args=["lfs","unlock","--id="+approved_id,"--json"]
    if foreign:args.append("--force")
    # Errors remain unresolved. Never fall back to a new ID or force by path.
    run(args)
    return approved_id
